using namespace moon::recent;
void check(bool value,const char* why){if(!value)throw std::runtime_error(why);}
int main(){try{std::vector<Project> values;record(values,"C:/A.PNG",1);record(values,"C:/b.moonsprite",2);togglePin(values,"C:/A.PNG");check(values[0].path=="C:/A.PNG"&&values[0].pinned,"Pin-first stable order");record(values,"C:/c.aseprite",3);check(values[0].path=="C:/A.PNG"&&values[1].path=="C:/c.aseprite","Reopen/new enters front of own partition");record(values,"C:/a.png",4);check(values.size()==4,"Exact original path string identity, no Windows normalization");record(values,"C:/A.PNG",5);check(values[0].pinned&&values[0].lastOpened==5&&values.size()==4,"Reopen retains pin and updates time");auto copy=decode(encode(values));check(copy.size()==4&&copy[0].pinned&&copy[0].lastOpened==5,"Metadata codec roundtrip");reorder(values,{"C:/b.moonsprite","C:/A.PNG","C:/b.moonsprite"});check(values[0].path=="C:/A.PNG"&&values[1].path=="C:/b.moonsprite","Legacy reordered paths dedupe and pinned partition");clear(values);check(values.size()==1&&values[0].pinned,"Clear keeps pinned metadata");remove(values,"C:/A.PNG");check(values.empty(),"Explicit removal can remove pinned metadata");check(!record(values,"C:/script.lua",5)&&values.empty(),"Only legacy admitted file types");for(int i=0;i<30;++i)record(values,"C:/"+std::to_string(i)+".png",i);check(values.size()==24&&values.front().path=="C:/29.png","Legacy 24 record cap");auto old=decode("\"D:/old work/a.png\"\n\"D:/b.moonsprite\"\n",true);check(old.size()==2&&old[0].path=="D:/old work/a.png"&&!old[0].pinned,"Preserve old native home-recent.txt order/paths");std::cout<<"Recent project checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
